115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        if (!normalizeAndValidateFields(owner)) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
123	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
127	        owner.setRegistrationDate(registrationDate);
128	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
129	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
130	        }
131	        owner.setIdentityKey(identityKey(owner));
132	        if (isDuplicate(owner)) {
133	            return new ResponseEntity<>(HttpStatus.CONFLICT);
134	        }
135	        if (countOwnersInCity(owner.getCity()) >= 50) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        assignRegistrationAttributes(owner);
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
142	        HttpHeaders headers = new HttpHeaders();
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
146	    }
147	
148	    /**
149	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
150	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
151	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
152	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
153	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
154	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
155	     */
156	    private boolean normalizeAndValidateFields(Owner owner) {
157	        String address = normalizeAddress(owner.getAddress());
158	        if (address.isEmpty()) {
159	            return false;
160	        }
161	        owner.setAddress(address);
162	        if (owner.getEmail() != null) {
163	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
164	            if (!EMAIL_PATTERN.matcher(email).matches()) {
165	                return false;
166	            }
167	            owner.setEmail(email);
168	        }
169	        if (!isPostcodeValidForCity(owner)) {
170	            return false;
171	        }
172	        String telephone = normalizeTelephone(owner.getTelephone());
173	        if (telephone == null) {
174	            return false;
175	        }
176	        owner.setTelephone(telephone);
177	        return true;
178	    }
179	
180	    /**
181	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
182	     * computed against the owner population rather than carried on the owner itself (currently the
183	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
184	     * listing intentionally omits these flags.
185	     */
186	    private OwnerDto buildOwnerDto(Owner owner) {
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
189	        return ownerDto;
190	    }
