293	    /** Matches a well-formed postcode: exactly 4 digits. */
294	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
295	
296	    /**
297	     * Region -> inclusive 4-digit postcode range {low, high}. A city's region is derived from the
298	     * fixed city-to-region table ({@link Owner#getRegion()}); a region absent from this map (i.e.
299	     * {@code UNKNOWN}) carries no range rule and accepts any 4-digit postcode.
300	     */
301	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
302	        "NSW", new int[] {2000, 2099},
303	        "VIC", new int[] {3000, 3099},
304	        "QLD", new int[] {4000, 4099});
305	
306	    /**
307	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
308	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
309	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
310	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode.
311	     */
312	    private static boolean isPostcodeValidForCity(Owner owner) {
313	        String postcode = owner.getPostcode();
314	        if (postcode == null) {
315	            return true;
316	        }
317	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
318	            return false;
319	        }
320	        int[] range = REGION_POSTCODE_RANGES.get(owner.getRegion());
321	        if (range == null) {
322	            return true;
323	        }
324	        int value = Integer.parseInt(postcode);
325	        return value >= range[0] && value <= range[1];
326	    }
327	
328	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
329	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
330	
331	    /**
332	     * Required national-number length per country code: '+61' (Australia) expects 9 national
333	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
334	     * national part is not the required length is rejected.
335	     */
336	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
337	        "+61", 9, "+1", 10);
338	
339	    /**
340	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
341	     * code are kept when present; otherwise country code '+61' is assumed and a single
342	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
343	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
344	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
345	     * Returns {@code null} when the number cannot form a valid E.164 value.
346	     */
347	    private static String normalizeTelephone(String telephone) {
348	        if (telephone == null) {
349	            return null;
350	        }
351	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
352	        String e164;
353	        if (cleaned.startsWith("+")) {
354	            e164 = cleaned;
355	        } else {
356	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
357	            e164 = "+61" + national;
358	        }
359	        if (!E164_PATTERN.matcher(e164).matches()) {
360	            return null;
361	        }
362	        return hasValidNationalNumberLength(e164) ? e164 : null;
363	    }
364	
365	    /**
366	     * Whether the national number of a well-formed E.164 value has the length required for its
367	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
368	     * per-country length rule and are accepted.
369	     */
370	    private static boolean hasValidNationalNumberLength(String e164) {
371	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
372	            String countryCode = entry.getKey();
373	            if (e164.startsWith(countryCode)) {
374	                return e164.length() - countryCode.length() == entry.getValue();
375	            }
376	        }
377	        return true;
378	    }
379	
380	    /**
381	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
382	     * code, membership number, household id, namesake count and household member count. Each is
383	     * derived from the owner's already-normalized fields and the existing owner population, so this
384	     * must run before the owner is saved, while the counts still exclude the owner being created.
385	     */
386	    private void assignRegistrationAttributes(Owner owner) {
387	        owner.setCustomerCode(generateCustomerCode(owner));
388	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
389	        owner.setHouseholdId(householdId(owner));
390	        owner.setNamesakeCount(countNamesakes(owner));
391	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
392	    }
393	
394	    /**
395	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
396	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
397	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
398	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
399	     * function of the region and the (telephone, last name) pair.
400	     */
401	    private String generateCustomerCode(Owner owner) {
402	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
403	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
404	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
405	        return owner.getRegion() + "-" + hash8;
406	    }
407	
408	    /**
409	     * The number of existing owners registered in {@code city}, compared case-insensitively
410	     * with collapsed whitespace.
411	     */
412	    private int countOwnersInCity(String city) {
413	        String normalized = normalizeHouseholdField(city);
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
416	            .count();
417	    }
418	
419	    /**
420	     * The effective registration date to store for a new owner: the date supplied on the request
421	     * when present, otherwise the current server date, in either case rolled forward to a business
422	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
423	     * This single point of resolution is what every registration-date-derived value (the stored
424	     * date, the membership number's year segment, the per-day create-limit) is computed from.
425	     */
426	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
427	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
428	        return toBusinessDay(date);
429	    }
430	
431	    /**
432	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
433	     * following Monday; a weekday is returned unchanged.
434	     */
435	    private static LocalDate toBusinessDay(LocalDate date) {
436	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
437	            date = date.plusDays(1);
438	        }
439	        return date;
440	    }
441	
442	    /**
443	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
444	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
445	     */
446	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
447	        String yy = String.format("%02d", registrationDate.getYear() % 100);
448	        return customerCode + "-M" + yy;
449	    }
450	
451	    /**
452	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
453	     * last name, compared case-insensitively.
454	     */
455	    private int countNamesakes(Owner owner) {
456	        String firstName = normalizeHouseholdField(owner.getFirstName());
457	        String lastName = normalizeHouseholdField(owner.getLastName());
458	        return (int) this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
460	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
461	            .count();
462	    }
463	
464	    /**
465	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
466	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
467	     * unusually high daily signup volume.
468	     */
469	    private boolean isBulkSignupWarning() {
470	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
471	    }
472	
473	    /** The number of existing owners whose registration date is {@code date}. */
474	    private int countOwnersRegisteredOn(LocalDate date) {
475	        return (int) this.clinicService.findAllOwners().stream()
476	            .filter(existing -> date.equals(existing.getRegistrationDate()))
477	            .count();
478	    }
479	
480	    /**
481	     * The single derived key all duplicate detection flows through, formed from the owner's
482	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
483	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
484	     * id is derived, so the household segment is empty at that point. Because the telephone is part
485	     * of the key, two owners in the same household with different telephones resolve to different
486	     * keys and are both allowed.
487	     */
488	    private static String identityKey(Owner owner) {
489	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
490	        String email = owner.getEmail() == null ? "" : owner.getEmail();
491	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
492	        return telephone + "|" + email + "|" + household;
493	    }
494	
495	    /**
496	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
497	     * duplicate condition: the previously separate telephone, email and household checks are now all
498	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
499	     * trips it is rejected with {@code 409 CONFLICT}.
500	     */
501	    private boolean isDuplicate(Owner owner) {
502	        String key = owner.getIdentityKey();
503	        return this.clinicService.findAllOwners().stream()
504	            .map(Owner::getIdentityKey)
505	            .filter(existing -> existing != null)
506	            .anyMatch(key::equals);
507	    }
508	
509	    /** Common street-type abbreviations expanded during address normalization. */
510	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
511	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
512	
513	    /**
514	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
515	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
516	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
517	     * string when {@code address} is null or blank after normalization.
518	     */
519	    private static String normalizeAddress(String address) {
520	        if (address == null) {
521	            return "";
522	        }
523	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
524	        if (collapsed.isEmpty()) {
525	            return "";
526	        }
527	        StringBuilder sb = new StringBuilder(collapsed.length());
528	        for (String token : collapsed.split(" ")) {
529	            if (sb.length() > 0) {
530	                sb.append(' ');
531	            }
532	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
533	        }
534	        return sb.toString();
535	    }
536	
537	    /**
538	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
539	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
540	     */
541	    private static String normalizeHouseholdField(String value) {
542	        if (value == null) {
543	            return "";
544	        }
545	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
546	    }
547	
548	    /**
549	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
550	     * same address compared case-insensitively with collapsed whitespace.
551	     */
552	    private List<Owner> findHousemates(Owner owner) {
553	        String lastName = normalizeHouseholdField(owner.getLastName());
554	        String address = normalizeHouseholdField(owner.getAddress());
555	        return this.clinicService.findAllOwners().stream()
556	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
557	                && normalizeHouseholdField(existing.getAddress()).equals(address))
558	            .toList();
559	    }
560	
561	    /**
562	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
563	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
564	     */
565	    private int countHouseholdMembers(Owner owner) {
566	        return findHousemates(owner).size() + 1;
567	    }
568	
569	    /**
570	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
571	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
572	     * deterministically from those normalized fields so housemates always resolve to the same value,
573	     * regardless of registration order.
574	     */
575	    private static String householdId(Owner owner) {
576	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
577	            + normalizeHouseholdField(owner.getAddress());
578	        return sha256Hex(key).substring(0, 24);
579	    }
580	
581	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
582	    private static String sha256Hex(String input) {
583	        try {
584	            byte[] digest = MessageDigest.getInstance("SHA-256")
585	                .digest(input.getBytes(StandardCharsets.UTF_8));
586	            StringBuilder sb = new StringBuilder(digest.length * 2);
587	            for (byte b : digest) {
588	                sb.append(String.format("%02X", b));
589	            }
590	            return sb.toString();
591	        }
592	        catch (NoSuchAlgorithmException e) {
593	            throw new IllegalStateException("SHA-256 not available", e);
594	        }
595	    }
596	}
